changeSet.sql:
-- Bo'lim mudiri (epidim_head) -> ATTACH_ACT: READ, ASSIGN, UPDATE INSERT INTO role_permissions (role_id, permission_id, version, created_at, updated_at) SELECT r.id, p.id, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM role r, permission p WHERE r.name = 'isemid_epidim_head' AND p.subject = 'ATTACH_ACT' ON CONFLICT (role_id, permission_id) DO NOTHING;
INSERT INTO role_permission_actions (role_permission_id, action_id) SELECT rp.id, a.id FROM role_permissions rp JOIN role r ON r.id = rp.role_id JOIN permission p ON p.id = rp.permission_id JOIN action a ON a.code IN ('READ', 'ASSIGN', 'UPDATE') WHERE r.name = 'isemid_epidim_head' AND p.subject = 'ATTACH_ACT' ON CONFLICT (role_permission_id, action_id) DO NOTHING;
-- Epidemiolog -> ATTACH_ACT: READ, UPDATE INSERT INTO role_permissions (role_id, permission_id, version, created_at, updated_at) SELECT r.id, p.id, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM role r, permission p WHERE r.name = 'isemid_epidemiologist' AND p.subject = 'ATTACH_ACT' ON CONFLICT (role_id, permission_id) DO NOTHING;
INSERT INTO role_permission_actions (role_permission_id, action_id) SELECT rp.id, a.id FROM role_permissions rp JOIN role r ON r.id = rp.role_id JOIN permission p ON p.id = rp.permission_id JOIN action a ON a.code IN ('READ', 'UPDATE') WHERE r.name = 'isemid_epidemiologist' AND p.subject = 'ATTACH_ACT' ON CONFLICT (role_permission_id, action_id) DO NOTHING;
-- Yordamchi (assistant_epidemiologist) -> ATTACH_ACT: READ, UPDATE INSERT INTO role_permissions (role_id, permission_id, version, created_at, updated_at) SELECT r.id, p.id, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM role r, permission p WHERE r.name = 'isemid_assistant_epidemiologist' AND p.subject = 'ATTACH_ACT' ON CONFLICT (role_id, permission_id) DO NOTHING;
INSERT INTO role_permission_actions (role_permission_id, action_id) SELECT rp.id, a.id FROM role_permissions rp JOIN role r ON r.id = rp.role_id JOIN permission p ON p.id = rp.permission_id JOIN action a ON a.code IN ('READ', 'UPDATE') WHERE r.name = 'isemid_assistant_epidemiologist' AND p.subject = 'ATTACH_ACT' ON CONFLICT (role_permission_id, action_id) DO NOTHING;

-- Super Admin -> ATTACH_ACT INSERT INTO role_permissions (role_id, permission_id, version, created_at, updated_at) SELECT r.id, p.id, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM role r, permission p WHERE r.name = 'isemid_super_admin' AND p.subject = 'ATTACH_ACT' ON CONFLICT (role_id, permission_id) DO NOTHING;
INSERT INTO role_permission_actions (role_permission_id, action_id) SELECT rp.id, a.id FROM role_permissions rp JOIN role r ON r.id = rp.role_id JOIN permission p ON p.id = rp.permission_id CROSS JOIN action a WHERE r.name = 'isemid_super_admin' AND p.subject = 'ATTACH_ACT' AND a.deleted = false ON CONFLICT (role_permission_id, action_id) DO NOTHING;
-- Admin -> ATTACH_ACT (DELETE va MANAGE'dan tashqari) INSERT INTO role_permissions (role_id, permission_id, version, created_at, updated_at) SELECT r.id, p.id, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM role r, permission p WHERE r.name = 'isemid_admin' AND p.subject = 'ATTACH_ACT' ON CONFLICT (role_id, permission_id) DO NOTHING;
INSERT INTO role_permission_actions (role_permission_id, action_id) SELECT rp.id, a.id FROM role_permissions rp JOIN role r ON r.id = rp.role_id JOIN permission p ON p.id = rp.permission_id CROSS JOIN action a WHERE r.name = 'isemid_admin' AND p.subject = 'ATTACH_ACT' AND a.deleted = false AND a.code NOT IN ('DELETE', 'MANAGE') ON CONFLICT (role_permission_id, action_id) DO NOTHING;
